class MovementSystem:
    def run(self, world, dt):
        for e in world.query(Position, Velocity):
            p, v = e.get(Position), e.get(Velocity)
            p.x += v.x * dt
            p.y += v.y * dt

class CollisionSystem:
    def run(self, world, dt):
        world.grid.rebuild(world.query(Position, Collider))
        for e in world.query(Position, Collider):
            for o in world.grid.near(e):
                if overlaps(e, o):
                    world.events.emit(Collision(e, o))

